class Solution {
public:
    int maxIncreaseKeepingSkyline(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<int> row_max(n, 0), col_max(n, 0);
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                row_max[r] = max(row_max[r], grid[r][c]);
                col_max[c] = max(col_max[c], grid[r][c]);
            }
        }
        int ans = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                ans += min(row_max[r], col_max[c]) - grid[r][c];
            }
        }
        return ans;
    }
};

class Solution {
    public int maxIncreaseKeepingSkyline(int[][] grid) {
        int n = grid.length;
        int[] rowMax = new int[n];
        int[] colMax = new int[n];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                rowMax[r] = Math.max(rowMax[r], grid[r][c]);
                colMax[c] = Math.max(colMax[c], grid[r][c]);
            }
        }
        int ans = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                ans += Math.min(rowMax[r], colMax[c]) - grid[r][c];
            }
        }
        return ans;
    }
}

var maxIncreaseKeepingSkyline = function(grid) {
    const n = grid.length;
    const rowMax = new Array(n).fill(0);
    const colMax = new Array(n).fill(0);
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            rowMax[r] = Math.max(rowMax[r], grid[r][c]);
            colMax[c] = Math.max(colMax[c], grid[r][c]);
        }
    }
    let ans = 0;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            ans += Math.min(rowMax[r], colMax[c]) - grid[r][c];
        }
    }
    return ans;
};
